setInterval(() => { const b = $('#banner .track'); if (!b || document.hidden) return; const w = b.clientWidth, n = b.children.length, i = Math.round(b.scrollLeft / w); b.scrollTo({ left: ((i + 1) % n) * w, behavior: 'smooth' }); }, 4200);
